import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import static org.junit.Assert.*;

public class UrlBuilderTest {

    @Test
    public void urlBuilderTest() {
        try {
            URL inputUrl = new URL("https://www.example.com");
            UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
            assertNotNull(urlBuilder);
        } catch (MalformedURLException mue) {
            fail("MalformedURLException should not have been thrown.");
        }
    }

    @Test
    public void urlBuilderBuildTest() {
        try {
            URL inputUrl = new URL("https://www.example.com");
            UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
            URL outputUrl = urlBuilder.build();
            assertNotNull(outputUrl);
            assertEquals(inputUrl, outputUrl);
        } catch (MalformedURLException mue) {
            fail("MalformedURLException should not have been thrown.");
        }
    }

    @Test
    public void appendKeyValTest() {
        try {
            URL inputUrl = new URL("https://www.example.com");
            Connection.KeyVal kv = mock(Connection.KeyVal.class);
            when(kv.key()).thenReturn("key");
            when(kv.value()).thenReturn("value");

            UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
            urlBuilder.appendKeyVal(kv);

            URL outputUrl = urlBuilder.build();
            assertNotNull(outputUrl);
            assertTrue(outputUrl.toString().contains("key=value"));
        } catch (MalformedURLException | UnsupportedEncodingException e) {
            fail("Exception should not have been thrown.");
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingExceptionTest() throws UnsupportedEncodingException {
        try {
            URL inputUrl = new URL("https://www.example.com");
            Connection.KeyVal kv = mock(Connection.KeyVal.class);
            when(kv.key()).thenReturn("\uD800");
            when(kv.value()).thenReturn("value");

            UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
            urlBuilder.appendKeyVal(kv);
        } catch (MalformedURLException mue) {
            fail("MalformedURLException should not have been thrown.");
        }
    }
}
```
